cache='raw/us/geocode.json'
G=json.load(open(cache)) if os.path.exists(cache) else {}
def geo(q):
    if q in G: return G[q]
    u='https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+urllib.parse.quote(q+', USA')
    r=urllib.request.Request(u,headers={'User-Agent':'eruvmap-research/1.0 (public-source verification)'})
    d=json.load(urllib.request.urlopen(r,timeout=30)); time.sleep(1.2)
    G[q]=[float(d[0]['lon']),float(d[0]['lat']),d[0]['display_name'],d[0]['osm_type']+'/'+str(d[0]['osm_id'])] if d else None
    json.dump(G,open(cache,'w'),indent=1); return G[q]
feats=[];fail=[]
for (slug,name,city,st,q,src,url,mk,mu,terms,status,asof,hot,ev,note) in R:
    g=geo(q)
    if not g: fail.append(q); continue
    p=dict(id='us-'+slug,name_en=name,city=city,country='US',state=st,geometry_kind='point',status=status,source=src,source_url=url,
      license='Facts compiled from official community source; no geometry reused',verified_at='2026-10-17',contact_url=url,
      geometry_precision='approximate',note='Representative location only; check the official map and status')
    if asof: p['status_as_of']=asof
    p['official_boundary_map']=mk
    if mu: p['boundary_map_url']=mu
    p['stated_terms']=terms
    if hot: p['hotline_or_contact']=hot
    p['evidence']='official page fetched 2026-10-17' if ev==F else 'official page text seen via search-index snapshot; direct fetch blocked/failed 2026-10-17'
    p['coordinate_source']='Nominatim/OSM geocode of "%s" (%s, ODbL)'%(q,g[3])
    if note: p['extra_note']=note
    feats.append(dict(type='Feature',properties=p,geometry=dict(type='Point',coordinates=[round(g[0],5),round(g[1],5)])))
json.dump(dict(type='FeatureCollection',features=feats),open('us-eruvs.geojson','w'),indent=1,ensure_ascii=False)
print(len(feats),'features; geocode failures:',fail)
